using System.Text.Json;
using Microsoft.Xna.Framework;
using static StarlightSyndicateDemo.HudCanvas;
namespace StarlightSyndicateDemo;
internal sealed record FittingPurchase(string Id,int Quantity,decimal MaxPrice,decimal Total,string Error="");
internal static class FittingPurchases
{
 internal static List<FittingPurchase> Plan(DemoWorld w,Ship fit){var need=FittingDesignStore.Equipment(fit);var owned=w.Player.CombatHull==fit.CombatHull?FittingDesignStore.Equipment(w.Player):new Dictionary<string,int>();if(w.Player.CombatHull==fit.CombatHull)for(int i=0;i<w.Player.Rigs.Length;i++){string id=w.Player.Rigs[i];if(id.Length>0&&id!=fit.Rigs.ElementAtOrDefault(i))owned[id]=Math.Max(0,owned.GetValueOrDefault(id)-1);}
 if(w.Player.CombatHull!=fit.CombatHull&&ItemCatalog.All.Any(i=>i.Id==fit.CombatHull)){need[fit.CombatHull]=1;owned[fit.CombatHull]=w.FleetBerths.Count(b=>b.System==w.StationKey44&&b.Ship.CombatHull==fit.CombatHull);}
 var rows=new List<FittingPurchase>();foreach(var (id,count) in need){int missing=Math.Max(0,count-owned.GetValueOrDefault(id)-(int)w.ItemCount(id,true));if(missing==0)continue;int remaining=missing;decimal total=0,max=0;foreach(var offer in w.Offers(id,w.StationKey44,false).OrderBy(o=>o.Price)){int n=Math.Min(remaining,offer.Remaining);total+=n*offer.Price;max=offer.Price;remaining-=n;if(remaining==0)break;}rows.Add(new(id,missing,max,total,remaining>0?"Insufficient local sell orders":""));}return rows;}
 internal static string Buy(DemoWorld live,Ship fit){var plan=Plan(live,fit);if(plan.Any(p=>p.Error.Length>0))return "Missing local sell orders; no purchases made.";var stage=JsonSerializer.Deserialize<DemoWorld>(JsonSerializer.Serialize(live,FittingDesignStore.Json),FittingDesignStore.Json)!;stage.Player=FittingSimulation.Copy(live.Player);foreach(var row in plan){float before=stage.ItemCount(row.Id,true);string error=stage.SubmitMarket(row.Id,stage.StationKey44,true,row.Quantity,row.MaxPrice,0,true);if(stage.ItemCount(row.Id,true)<before+row.Quantity)return error+" No purchases made.";}live.MarketOrders=stage.MarketOrders;live.MarketTrades=stage.MarketTrades;live.WalletJournal=stage.WalletJournal;live.WalletFunds=stage.WalletFunds;live.SeededMarkets=stage.SeededMarkets;live.StationItems=stage.StationItems;live.Say("Purchased fitting equipment into station hangar.");return "";}
}
public sealed partial class DemoGame
{
 bool fitBuyDialog;int fitBuyPage;
 void OpenFitPurchase(){fitBuyDialog=true;fitBuyPage=0;}
 void DrawFitPurchases(){var plan=FittingPurchases.Plan(world,FittingWorld.Player);ui.Box(new(491,256,597,400),new Color(7,16,21));ui.Border(new(491,256,597,400),Cyan);ui.Hits.Add(new(new(491,256,597,400),()=>{},"Fitting purchase dialog"));ui.Text("BUY MISSING FITTING EQUIPMENT",509,272,Cyan,17);ui.Text("Delivered to "+world.Current.Name+" item hangar",509,301,Muted,12);int y=331;foreach(var row in plan.Skip(fitBuyPage*9).Take(9)){ui.Text(ShortInfo(DemoWorld.ItemName(row.Id),46),510,y,White,12);ui.Text("x"+row.Quantity,877,y,Cyan,12);ui.Text(row.Error.Length>0?"Unavailable":row.Total.ToString("0.00")+" CR",937,y,row.Error.Length>0?Red:Gold,11);y+=25;}ui.Text($"Total: {plan.Sum(p=>p.Total):0.00} CR / {plan.Count} item types",510,565,Gold,14);ui.Button(new(510,605,150,30),"Previous",()=>fitBuyPage=Math.Max(0,fitBuyPage-1));ui.Button(new(668,605,120,30),"Next",()=>fitBuyPage=Math.Min(Math.Max(0,(plan.Count-1)/9),fitBuyPage+1));ui.Button(new(796,605,153,30),"Buy missing",()=>{fitNotice=FittingPurchases.Buy(world,FittingWorld.Player);if(fitNotice.Length==0){fitNotice="Purchased missing equipment into station hangar.";fitBuyDialog=false;}},"Confirm fitting purchase");ui.Button(new(956,605,113,30),"Cancel",()=>fitBuyDialog=false);}
 string fitCapProjectionKey="",fitCapProjection="";
 string FitCapStatus(Ship s){if(!double.IsNaN(s.CapacitorStableFraction))return $"Stable {s.CapacitorStableFraction:P0}";string key=$"{s.MaxCap:R}/{s.CapacitorUse:R}/{s.Stat("rechargeRate"):R}";if(key==fitCapProjectionKey)return fitCapProjection;fitCapProjectionKey=key;double cap=s.MaxCap,time=0,recharge=s.Stat("rechargeRate")/1000;for(int i=0;i<28800&&cap>s.MaxCap*.01;i++){double x=Math.Clamp(cap/s.MaxCap,0,1);cap+=(10*s.MaxCap/Math.Max(.001,recharge)*(Math.Sqrt(x)-x)-s.CapacitorUse)*.25;time+=.25;}return fitCapProjection=time>=7200?"Depletes >2 hours":"Depletes "+TimeSpan.FromSeconds(time).ToString(@"mm\:ss");}
}
